/**
 * Vector Store Inventory — tool-local actions.
 *
 * Category: AI / LLM Product Management (squad S12b)
 * Tool:     Catalog of embedding collections — model, dim, doc count,
 *           refresh cadence, owner, downstream consumers.
 *
 * Agent surface: tool.vector_store_inventory.*
 * Backing CRUD : workspace.vector_collection.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (see hallucination-log.ts for the analog) ──
 * Collections are a record-keeping entity — generic create / list / update /
 * delete already exist via workspace.vector_collection.*. This file adds:
 *
 *   1. list_state        — total collections + totalDocs + byEmbeddingModel
 *                          rollup (collections + docs per model).
 *   2. add_collection    — register an embedding collection.
 *   3. update_doc_count  — refresh a collection's docCount by id → {updated}.
 *
 * Entity kind "workspace:vectorCollection" (kindFromToolId of
 * "workspace.vector_collection") matches the browser sync engine, so MCP
 * writes round-trip into the UI.
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { VectorCollection } from "@/lib/stores/workspace-types";

const KIND_VECTOR = "workspace:vectorCollection";

const ws = () => useWorkspaceStore.getState();

function summarize(items: VectorCollection[]) {
  let totalDocs = 0;
  const byEmbeddingModel: Record<string, { collections: number; docs: number }> = {};
  for (const c of items) {
    totalDocs += c.docCount;
    const m = byEmbeddingModel[c.embeddingModel] ?? { collections: 0, docs: 0 };
    m.collections += 1;
    m.docs += c.docCount;
    byEmbeddingModel[c.embeddingModel] = m;
  }
  return {
    total: items.length,
    totalDocs,
    byEmbeddingModel,
    items,
  };
}

// ──────── tool.vector_store_inventory.list_state ────────
registry.register({
  id: "tool.vector_store_inventory.list_state",
  toolId: "tool.vector_store_inventory",
  name: "list_state",
  category: "read",
  description:
    "List all vector collections with summary. Returns {total, totalDocs, byEmbeddingModel: Record<model, {collections, docs}>, items}.",
  paramsSchema: z.object({}),
  handler: async () => summarize(ws().vectorCollections ?? []),
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<VectorCollection>(ctx.userId, KIND_VECTOR);
    return summarize(items);
  },
});

// ──────── tool.vector_store_inventory.add_collection ────────
registry.register({
  id: "tool.vector_store_inventory.add_collection",
  toolId: "tool.vector_store_inventory",
  name: "add_collection",
  category: "write",
  requiresConfirmation: false,
  description:
    "Register an embedding collection. dim is the embedding dimensionality; docCount is the current number of indexed documents; consumers lists downstream features/services. Returns {added: true, id}.",
  paramsSchema: z.object({
    name: z.string().min(1).max(200),
    embeddingModel: z.string().min(1).max(200),
    dim: z.number().int().positive(),
    docCount: z.number().int().min(0),
    refreshCadence: z.string().max(200).optional().describe("Free-text, e.g. 'daily'."),
    owner: z.string().max(200).optional(),
    consumers: z.array(z.string()).optional(),
    notes: z.string().max(2000).optional(),
  }),
  handler: async (params) => {
    const entry: VectorCollection = { id: crypto.randomUUID(), ...params };
    ws().upsertVectorCollection(entry);
    return { added: true, id: entry.id };
  },
  mcpHandler: async (params, ctx) => {
    const entry: VectorCollection = { id: crypto.randomUUID(), ...params };
    await serverUpsertEntity<VectorCollection>(ctx.userId, KIND_VECTOR, entry);
    return { added: true, id: entry.id };
  },
});

// ──────── tool.vector_store_inventory.update_doc_count ────────
// Collections grow/shrink as they're re-indexed; refreshing the count is the
// most common edit. Additive in spirit (one field) → no confirmation.
registry.register({
  id: "tool.vector_store_inventory.update_doc_count",
  toolId: "tool.vector_store_inventory",
  name: "update_doc_count",
  category: "write",
  requiresConfirmation: false,
  description:
    "Update a collection's docCount after a re-index. Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    docCount: z.number().int().min(0),
  }),
  handler: async (params) => {
    const current = (ws().vectorCollections ?? []).find((c) => c.id === params.id);
    if (!current) return { updated: false };
    ws().upsertVectorCollection({ ...current, docCount: params.docCount });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<VectorCollection>(ctx.userId, KIND_VECTOR, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<VectorCollection>(ctx.userId, KIND_VECTOR, {
      ...current,
      docCount: params.docCount,
    });
    return { updated: true };
  },
});
